import"chrome://resources/cr_elements/cr_tab_box/cr_tab_box.js";import{assert}from"chrome://resources/js/assert.js";import{addWebUiListener}from"chrome://resources/js/cr.js";import{CustomElement}from"chrome://resources/js/custom_element.js";import{getTemplate}from"./app.html.js";import{MetricsInternalsBrowserProxyImpl}from"./browser_proxy.js";import{getEventsPeekString,logEventToString,sizeToString,timestampToString,umaLogTypeToString}from"./log_utils.js";import{updateStructuredMetricsEvents,updateStructuredMetricsSummary}from"./structured/structured_utils.js";const EMPTY_LOG={type:"N/A",hash:"N/A",timestamp:"",size:-1,events:[]};export class MetricsInternalsAppElement extends CustomElement{static get is(){return"metrics-internals-app"}static get template(){return getTemplate()}initPromise;browserProxy_=MetricsInternalsBrowserProxyImpl.getInstance();previousVariationsSummaryData_="";previousUmaSummaryData_="";constructor(){super();this.initPromise=this.init_()}getUmaLogsExportContent(){return this.browserProxy_.getUmaLogData(true)}async init_(){await this.updateVariationsSummary_();setInterval((()=>this.updateVariationsSummary_()),3e3);await this.updateUmaSummary_();setInterval((()=>this.updateUmaSummary_()),3e3);await this.updateStructuredMetricsEvents_();setInterval((()=>this.updateStructuredMetricsSummary_()),5e3);const eventRefreshButton=this.$("#sm-refresh-events");eventRefreshButton.addEventListener("click",(()=>this.updateStructuredMetricsEvents_()));const umaTableCaption=this.$("#uma-table-caption");const isUsingMetricsServiceObserver=await this.browserProxy_.isUsingMetricsServiceObserver();umaTableCaption.textContent=isUsingMetricsServiceObserver?"List of all UMA logs closed since browser startup.":"List of UMA logs closed since opening this page. Starting the browser         with the --export-uma-logs-to-file command line flag will instead show         all logs closed since browser startup.";addWebUiListener("uma-log-created-or-event",(()=>this.updateUmaLogsData_()));await this.updateUmaLogsData_();const exportUmaLogsButton=this.$("#export-uma-logs");exportUmaLogsButton.addEventListener("click",(()=>this.exportUmaLogs_()))}toggleEventsExpand_(e){let umaLogEventsDiv=e.target;while(!umaLogEventsDiv.classList.contains("uma-log-events")){umaLogEventsDiv=umaLogEventsDiv.parentElement}umaLogEventsDiv.classList.toggle("uma-log-events-expanded")}updateSummaryTable_(tableBody,summary){tableBody.replaceChildren();const template=this.$("#summary-row-template");for(const info of summary){const row=template.content.cloneNode(true);const[key,value]=row.querySelectorAll("td");assert(key);key.textContent=info.key;assert(value);value.textContent=info.value;tableBody.appendChild(row)}}async updateVariationsSummary_(){const summary=await this.browserProxy_.fetchVariationsSummary();const variationsSummaryTableBody=this.$("#variations-summary-body");const newDataString=summary.toString();if(newDataString===this.previousVariationsSummaryData_){return}this.previousVariationsSummaryData_=newDataString;this.updateSummaryTable_(variationsSummaryTableBody,summary)}async updateUmaSummary_(){const summary=await this.browserProxy_.fetchUmaSummary();const umaSummaryTableBody=this.$("#uma-summary-body");const newDataString=summary.toString();if(newDataString===this.previousUmaSummaryData_){return}this.previousUmaSummaryData_=newDataString;this.updateSummaryTable_(umaSummaryTableBody,summary)}updateLogsTable_(tableBody,logs){tableBody.replaceChildren();const template=this.$("#uma-log-row-template");for(const log of logs.slice(0).reverse()){const row=template.content.cloneNode(true);const[type,hash,timestamp,size,events]=row.querySelectorAll("td");assert(type);type.textContent=umaLogTypeToString(log.type);assert(hash);hash.textContent=log.hash;assert(timestamp);timestamp.textContent=timestampToString(log.timestamp);assert(size);size.textContent=sizeToString(log.size);assert(events);const eventsPeekDiv=events.querySelector(".uma-log-events-peek");assert(eventsPeekDiv);eventsPeekDiv.addEventListener("click",this.toggleEventsExpand_,false);const eventsPeekText=events.querySelector(".uma-log-events-peek-text");assert(eventsPeekText);eventsPeekText.textContent=getEventsPeekString(log.events);const eventsText=events.querySelector(".uma-log-events-text");assert(eventsText);for(const event of log.events.slice(0).reverse()){const div=document.createElement("div");div.textContent=logEventToString(event);eventsText.appendChild(div)}tableBody.appendChild(row)}}async updateUmaLogsData_(){const logsData=await this.browserProxy_.getUmaLogData(false);const logs=JSON.parse(logsData);if(!logs.logs.length){logs.logs=[EMPTY_LOG]}const umaLogsTableBody=this.$("#uma-logs-body");this.updateLogsTable_(umaLogsTableBody,logs.logs)}async exportUmaLogs_(){const logsData=await this.getUmaLogsExportContent();const file=new Blob([logsData],{type:"text/plain"});const a=document.createElement("a");a.href=URL.createObjectURL(file);a.download=`uma_logs_${(new Date).getTime()}.json`;a.click()}async updateStructuredMetricsSummary_(){const summary=await this.browserProxy_.fetchStructuredMetricsSummary();const template=this.$("#summary-row-template");const smSummaryBody=this.$("#sm-summary-body");updateStructuredMetricsSummary(smSummaryBody,summary,template)}async updateStructuredMetricsEvents_(){const events=await this.browserProxy_.fetchStructuredMetricsEvents();const eventTemplate=this.$("#structured-metrics-event-row-template");const eventDetailsTemplate=this.$("#structured-metrics-event-details-template");const kvTemplate=this.$("#summary-row-template");const eventTableBody=this.$("#sm-events-body");updateStructuredMetricsEvents(eventTableBody,events,eventTemplate,eventDetailsTemplate,kvTemplate)}}customElements.define(MetricsInternalsAppElement.is,MetricsInternalsAppElement);